/**
 * Shared API contract between backend and frontend (wave 2+).
 * Owned by the main session. Agents must not change it; ask instead.
 * Dates are ISO `YYYY-MM-DD` strings; money is USD.
 */

// --- search (S3, extended by S4/S5) ---------------------------------------

export interface SearchFilters {
  /** Exact country names, case-insensitive. Empty = any. */
  countries: string[];
  /** Canonical skill names from SKILLS. Candidate must have all of them. */
  skills: string[];
  minYears: number | null;
  maxYears: number | null;
  /** Annual USD, compared against the full-time monthly rate × 12. */
  minSalary: number | null;
  maxSalary: number | null;
}

export interface CandidateSummary {
  id: number;
  name: string;
  country: string;
  yearsExperience: number;
  /** Normalized full-time monthly rate; null when unverified. */
  monthlyRate: number | null;
  rateUnverified: boolean;
  availability: { fullTime: boolean; partTime: boolean; contractor: boolean; employee: boolean };
  biography: string;
  /** Up to 8 skills, strongest evidence first. */
  topSkills: string[];
}

export type MatchReasonKind =
  'skill' | 'experience' | 'salary' | 'country' | 'keyword' | 'semantic';

export interface MatchReason {
  kind: MatchReasonKind;
  /** Short human text, e.g. "React in 3 roles and bio". */
  label: string;
}

export interface SearchResult {
  candidate: CandidateSummary;
  /** Higher is better. Only meaningful within one response. */
  score: number;
  matchedSkills: string[];
  reasons: MatchReason[];
}

export interface SearchResponse {
  filters: SearchFilters;
  /** Candidates matching the filters, before the top-10 cut. */
  total: number;
  /** At most 10. */
  results: SearchResult[];
}

export interface FilterOptions {
  countries: { name: string; count: number }[];
  skills: { name: string; count: number }[];
}

export interface ApiError {
  error: string;
}

// --- profile (S6) ----------------------------------------------------------

export interface ProfileExperience {
  company: string;
  position: string;
  description: string;
  startDate: string | null;
  /** Raw end date from the data; null = open-ended. */
  endDate: string | null;
  /** End after the open-ended rules (S1 resolveJobs); null when not counted. */
  effectiveEndDate: string | null;
  counted: boolean;
  excludedReason: 'intern' | 'non-work' | 'no-start-date' | null;
}

export interface ProfileEducation {
  school: string;
  degree: string;
  startDate: string | null;
  endDate: string | null;
}

export interface ProfileSkill {
  name: string;
  inBio: boolean;
  roleCount: number;
}

export interface CandidateProfile {
  candidate: CandidateSummary;
  partTimeMonthlyRate: number | null;
  /** Newest first; jobs without a start date last. */
  experiences: ProfileExperience[];
  /** Newest first; entries without a start date last. */
  education: ProfileEducation[];
  /** Strongest evidence first. */
  skills: ProfileSkill[];
}
import {
  customType,
  index,
  int,
  primaryKey,
  real,
  sqliteTable,
  text,
} from 'drizzle-orm/sqlite-core';
import { z } from 'zod';

// --- CSV parsing helpers -------------------------------------------------
// The seed CSVs store everything as strings, so these coerce the raw values.

/** "" -> null, otherwise a Date. */
const csvDate = z.preprocess((val) => (val === '' ? null : val), z.coerce.date().nullish());

/** "true"/"false" (case-insensitive) or "1"/"0" -> boolean. */
const csvBoolean = z.preprocess((val) => {
  if (typeof val === 'boolean') return val;
  if (typeof val === 'string') {
    const v = val.trim().toLowerCase();
    return v === 'true' || v === '1';
  }
  return Boolean(val);
}, z.boolean());

/** "" -> null, otherwise a whole number (rates are rounded to whole dollars). */
const csvNumber = z.preprocess(
  (val) => (val === '' ? null : val),
  z.coerce.number().transform(Math.round).nullish()
);

// --- candidates ----------------------------------------------------------

export const candidateTable = sqliteTable('candidates', {
  id: int().primaryKey({ autoIncrement: true }),
  firstName: text().notNull(),
  lastName: text().notNull(),

  fullTime: int({ mode: 'boolean' }).notNull(),
  fullTimeStartDate: int({ mode: 'timestamp' }),
  /** Expected monthly rate in USD for full-time work. */
  fullTimeMonthlyRate: int(),

  partTime: int({ mode: 'boolean' }).notNull(),
  partTimeStartDate: int({ mode: 'timestamp' }),
  /** Expected monthly rate in USD for part-time work. */
  partTimeMonthlyRate: int(),

  contractor: int({ mode: 'boolean' }).notNull(),
  employee: int({ mode: 'boolean' }).notNull(),
  country: text().notNull(),
  biography: text(),

  // Derived at seed time (see src/lib/derive).
  /** Years of experience, overlaps merged, internships and breaks excluded. */
  yearsExperience: real().notNull().default(0),
  /** Full-time monthly rate if plausible (500-30000 USD), else null. */
  fullTimeRateNormalized: int(),
  /** Part-time monthly rate if plausible (500-30000 USD), else null. */
  partTimeRateNormalized: int(),
  /** true when the full-time rate is missing or implausible. */
  rateUnverified: int({ mode: 'boolean' }).notNull().default(false),
});

export const candidateInsertSchema = z.object({
  firstName: z.string(),
  lastName: z.string(),
  fullTime: csvBoolean,
  fullTimeStartDate: csvDate,
  fullTimeMonthlyRate: csvNumber,
  partTime: csvBoolean,
  partTimeStartDate: csvDate,
  partTimeMonthlyRate: csvNumber,
  contractor: csvBoolean,
  employee: csvBoolean,
  country: z.string(),
  biography: z.string().nullish(),
});

export type Candidate = typeof candidateTable.$inferSelect;
export type CandidateInsert = z.infer<typeof candidateInsertSchema>;

// --- education -----------------------------------------------------------

export const educationTable = sqliteTable('education', {
  id: int().primaryKey({ autoIncrement: true }),
  candidateId: int()
    .references(() => candidateTable.id)
    .notNull(),
  school: text().notNull(),
  degree: text().notNull(),
  startDate: int({ mode: 'timestamp' }),
  endDate: int({ mode: 'timestamp' }),
});

export const educationInsertSchema = z.object({
  candidateId: z.number(),
  school: z.string(),
  degree: z.string(),
  startDate: csvDate,
  endDate: csvDate,
});

export type Education = typeof educationTable.$inferSelect;
export type EducationInsert = z.infer<typeof educationInsertSchema>;

// --- experiences ---------------------------------------------------------

export const experienceTable = sqliteTable('experiences', {
  id: int().primaryKey({ autoIncrement: true }),
  candidateId: int()
    .references(() => candidateTable.id)
    .notNull(),
  company: text().notNull(),
  position: text().notNull(),
  description: text(),
  startDate: int({ mode: 'timestamp' }),
  endDate: int({ mode: 'timestamp' }),
});

export const experienceInsertSchema = z.object({
  candidateId: z.number(),
  company: z.string(),
  position: z.string(),
  description: z.string().default(''),
  startDate: csvDate,
  endDate: csvDate,
});

export type Experience = typeof experienceTable.$inferSelect;
export type ExperienceInsert = z.infer<typeof experienceInsertSchema>;

// --- candidate skills (derived) -------------------------------------------

export const candidateSkillTable = sqliteTable(
  'candidate_skills',
  {
    candidateId: int()
      .references(() => candidateTable.id)
      .notNull(),
    /** Canonical skill name from SKILLS. */
    skill: text().notNull(),
    /** Whether the skill was found in the biography. */
    inBio: int({ mode: 'boolean' }).notNull(),
    /** How many experiences mention it, in position or description. */
    roleCount: int().notNull(),
  },
  (table) => [
    primaryKey({ columns: [table.candidateId, table.skill] }),
    index('candidate_skills_skill_idx').on(table.skill),
  ]
);

export type CandidateSkill = typeof candidateSkillTable.$inferSelect;
export type CandidateSkillInsert = typeof candidateSkillTable.$inferInsert;

// --- candidate embeddings (derived) ----------------------------------------

/** Length of a text-embedding-3-small vector. */
export const EMBEDDING_DIMENSIONS = 1536;

/** libsql's native vector column: little-endian float32s, compared with vector_distance_cos. */
const f32Vector = customType<{ data: number[]; driverData: ArrayBuffer | Uint8Array }>({
  dataType: () => `F32_BLOB(${EMBEDDING_DIMENSIONS})`,
  toDriver: (value) => new Float32Array(value).buffer,
  // Copy first: the driver may hand back a byte view that isn't 4-byte aligned.
  fromDriver: (value) => Array.from(new Float32Array(new Uint8Array(value).slice().buffer)),
});

export const candidateEmbeddingTable = sqliteTable('candidate_embeddings', {
  candidateId: int()
    .primaryKey()
    .references(() => candidateTable.id),
  embedding: f32Vector().notNull(),
  /** sha256 hex of `model + '\n' + document`; unchanged hash means no re-embed. */
  contentHash: text().notNull(),
  model: text().notNull(),
});

export type CandidateEmbedding = typeof candidateEmbeddingTable.$inferSelect;
export type CandidateEmbeddingInsert = typeof candidateEmbeddingTable.$inferInsert;
import { drizzle } from 'drizzle-orm/libsql';
import * as schema from './schema';

/** Path to the SQLite file. Created and populated by `npm run db:seed`. */
export const DATABASE_URL = 'file:local.db';

/** Shared database client. */
export const db = drizzle({
  connection: { url: DATABASE_URL },
  casing: 'snake_case',
  schema,
});

export type Db = typeof db;
export interface JobInput {
  company: string;
  position: string;
  startDate: Date | null;
  endDate: Date | null;
}

export interface ResolvedJob extends JobInput {
  /** true if the job counts toward years of experience */
  counted: boolean;
  /** why it was not counted; null when counted */
  excludedReason: 'intern' | 'non-work' | 'no-start-date' | null;
  /** end date after applying the open-ended rules; null when not counted */
  effectiveEndDate: Date | null;
}

const MS_PER_DAY = 86_400_000;
const DAYS_PER_YEAR = 365.25;
const INTERN = /(?<![a-z0-9])(?:intern|interns|internship)(?![a-z0-9])/i;
const NON_WORK =
  /career break|career transition|career gap|sabbatical|trainee|student|volunteer|teaching assistant/i;

/** Whole UTC days since the epoch. */
const utcDay = (date: Date) => Math.floor(date.getTime() / MS_PER_DAY);

/** First matching exclusion rule for a job, or null when it counts. */
function exclusion(job: JobInput): ResolvedJob['excludedReason'] {
  const text = `${job.position}\n${job.company}`;
  if (INTERN.test(text)) return 'intern';
  if (NON_WORK.test(text)) return 'non-work';
  if (job.startDate === null) return 'no-start-date';
  return null;
}

/** Marks which jobs count and where each counted job effectively ends. Same order as the input. */
export function resolveJobs(jobs: JobInput[], today: Date): ResolvedJob[] {
  const reasons = jobs.map(exclusion);
  const openStarts = jobs
    .filter((job, i) => reasons[i] === null && job.endDate === null)
    .map((job) => job.startDate!);

  return jobs.map((job, i) => {
    const excludedReason = reasons[i];
    if (excludedReason !== null) {
      return { ...job, counted: false, excludedReason, effectiveEndDate: null };
    }

    let effectiveEndDate: Date;
    if (job.endDate !== null) {
      effectiveEndDate = utcDay(job.endDate) > utcDay(today) ? today : job.endDate;
    } else {
      // Ends at the next strictly later open-ended start, or today.
      const start = utcDay(job.startDate!);
      const next = openStarts
        .filter((date) => utcDay(date) > start)
        .sort((a, b) => a.getTime() - b.getTime())[0];
      effectiveEndDate = next ?? today;
    }
    return { ...job, counted: true, excludedReason: null, effectiveEndDate };
  });
}

/** Years with overlaps merged, rounded to 1 decimal. */
export function yearsOfExperience(jobs: JobInput[], today: Date): number {
  const periods = resolveJobs(jobs, today)
    .filter((job) => job.counted)
    .map((job) => [utcDay(job.startDate!), utcDay(job.effectiveEndDate!)])
    .filter(([start, end]) => end > start)
    .sort((a, b) => a[0] - b[0]);

  // Merge overlapping or touching periods and add up their days.
  let days = 0;
  let current: number[] | null = null;
  for (const [start, end] of periods) {
    if (current && start <= current[1]) {
      current[1] = Math.max(current[1], end);
    } else {
      if (current) days += current[1] - current[0];
      current = [start, end];
    }
  }
  if (current) days += current[1] - current[0];

  return Math.round((days / DAYS_PER_YEAR) * 10) / 10;
}
# CLAUDE.md

This file provides guidance to Claude Code (claude.ai/code) when working with code in this repository.

## Start here

Read `docs/PROGRESS.md` first. It has the current slice, the current step, and the one-line **Next action**. Read that slice's spec in `docs/slices/`, run the tests, then resume. At the end of a session: update PROGRESS.md, commit, and export the session into `ai-sessions/`.

## What this is

Take-home: a Next.js 16 (App Router, TypeScript, Tailwind) recruiter search over 1,000 anonymized engineers in SQLite, using Drizzle + libsql. Brief: `CHALLENGE.md`. Required features:

- filter search
- natural-language search (extract filters + match on resumes)
- top-10 results, each with a "why matched" explanation

## Commands

```bash
npm run dev          # http://localhost:3000
npm run db:seed      # migrate + load CSVs into local.db (skips if data exists)
npm run db:reset     # wipe and reload
npm run db:generate  # new migration after editing src/db/schema.ts
npm run lint
npm run typecheck
npm run format
npm test                              # vitest run (tests live in tests/)
npx vitest run tests/s1/rate.test.ts  # one file
npx vitest run -t "overlap"           # tests whose name matches
```

Evaluators run `npm install && npm run db:seed && npm run dev` from a clean checkout. Anything search needs, such as derived data, indexes or embeddings, must be produced by that path.

## Architecture

- `src/db/schema.ts`: Drizzle tables plus the Zod schemas that coerce raw CSV strings. `src/db/seed.ts` applies migrations, then loads `candidates.csv`, `education.csv` and `experiences.csv`. It maps each CSV `userId` to the auto-increment candidate `id`.
- `src/db/index.ts`: shared client, using `casing: 'snake_case'`. TypeScript fields are camelCase; the matching SQL columns are snake_case.
- `src/lib/openai.ts`: `getOpenAI()` and `embed()`, with models `text-embedding-3-small` and `gpt-4o-mini`. The only env var is `OPENAI_API_KEY`, set in `.env`.
- `next.config.ts` keeps `@libsql/client` out of the server bundle because it has native bindings, and sets `agentRules: false`.
- Schema change workflow: edit `schema.ts`, run `db:generate`, then `db:reset`. ESLint ignores `migrations/`.

## Data rules (agreed; see decision log in PROGRESS.md)

- Rates are **monthly USD**, but queries use annual amounts ("130k"). FT rates of `0`, under `500`, or over `30000` are unusable (mostly INR or annual figures from India). They're flagged unknown and left out of salary filters.
- Years of experience isn't stored; it's derived:
  - A job with no end date means the person is still there. It runs until the next open-ended job starts, or until today if it's the latest.
  - Open-ended jobs with the same start date all run to today.
  - Overlapping jobs are merged.
  - Internships and career breaks are excluded.
- There's no skills column. Skills come from bio, position and description text, plus embeddings.
- Countries are skewed: India 675, Brazil 227, no Canada. `Other` and `-` mean unknown.

## How work is done

- Build in vertical slices (S0–S7 in PROGRESS.md), in this order:
  1. tests
  2. backend
  3. frontend tests
  4. frontend
  5. check in the running app
  6. commit
- Commit messages start with the slice ID, e.g. `S3: filter API tests`.
- Tests and implementation are written by **separate agents** from the slice spec. The implementation agent never reads or edits test files. Test failures are relayed as "input → expected → got", not as test code.
- Independent slices, and the backend/frontend halves of one slice, run in parallel git worktrees. The API contract and mock fixture are committed first. The main session merges one branch at a time and reruns all tests.

## Style

Prettier: single quotes, semicolons, 100-character lines, `trailingComma: es5`. Path alias `@/*` → `src/*`.
import { and, asc, count, desc, eq, gte, inArray, lte, ne, sql, type SQL } from 'drizzle-orm';
import { db } from '@/db';
import {
  candidateSkillTable,
  candidateTable,
  type Candidate,
  type CandidateSkill,
} from '@/db/schema';
import type {
  CandidateSummary,
  FilterOptions,
  MatchReason,
  SearchFilters,
  SearchResponse,
} from '@/lib/contracts';

const TOP_N = 10;
const TOP_SKILLS = 8;

const usd = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
});

/** Evidence strength of one skill row: roles mentioning it, plus one for the bio. */
const strength = (row: CandidateSkill) => row.roleCount + (row.inBio ? 1 : 0);

/** Filter search (spec: docs/slices/S3-filter-search.md). Top 10 by skill score. */
export async function searchCandidates(filters: SearchFilters): Promise<SearchResponse> {
  const c = candidateTable;
  const cs = candidateSkillTable;
  const { countries, skills, minYears, maxYears, minSalary, maxSalary } = filters;

  const conditions: (SQL | undefined)[] = [];
  if (countries.length > 0) {
    conditions.push(
      inArray(
        sql`lower(${c.country})`,
        countries.map((country) => country.toLowerCase())
      )
    );
  }
  if (minYears !== null) conditions.push(gte(c.yearsExperience, minYears));
  if (maxYears !== null) conditions.push(lte(c.yearsExperience, maxYears));
  if (minSalary !== null || maxSalary !== null) {
    const annual = sql`${c.fullTimeRateNormalized} * 12`;
    conditions.push(eq(c.rateUnverified, false));
    if (minSalary !== null) conditions.push(gte(annual, minSalary));
    if (maxSalary !== null) conditions.push(lte(annual, maxSalary));
  }

  // Candidates with every requested skill, scored by summed evidence strength.
  const matched = db
    .select({
      candidateId: cs.candidateId,
      score: sql<number>`sum(${cs.roleCount} + ${cs.inBio})`.as('score'),
    })
    .from(cs)
    .where(inArray(cs.skill, skills))
    .groupBy(cs.candidateId)
    .having(sql`count(*) = ${skills.length}`)
    .as('matched');

  // With no skills every score is 0, so the order starts at years of experience.
  const hasSkills = skills.length > 0;
  const score = hasSkills ? matched.score : sql<number>`0`;
  const base = db
    .select({ candidate: c, score, total: sql<number>`count(*) over ()` })
    .from(c)
    .$dynamic();
  if (hasSkills) base.innerJoin(matched, eq(matched.candidateId, c.id));

  const rows = await base
    .where(and(...conditions))
    .orderBy(...(hasSkills ? [desc(score)] : []), desc(c.yearsExperience), asc(c.id))
    .limit(TOP_N);

  const skillRows = rows.length
    ? await db
        .select()
        .from(cs)
        .where(
          inArray(
            cs.candidateId,
            rows.map((row) => row.candidate.id)
          )
        )
    : [];

  const results = rows.map(({ candidate, score }) => {
    const own = skillRows.filter((row) => row.candidateId === candidate.id);
    const reasons: MatchReason[] = skills.map((skill) => ({
      kind: 'skill',
      label: skillLabel(own.find((row) => row.skill === skill)),
    }));
    reasons.push({ kind: 'experience', label: experienceLabel(candidate, filters) });
    if (minSalary !== null || maxSalary !== null) {
      reasons.push({ kind: 'salary', label: salaryLabel(candidate, filters) });
    }
    if (countries.length > 0) {
      reasons.push({ kind: 'country', label: `Based in ${candidate.country}` });
    }
    return {
      candidate: toSummary(candidate, own),
      score: Number(score),
      matchedSkills: [...skills],
      reasons,
    };
  });

  return { filters, total: rows[0]?.total ?? 0, results };
}

/** Countries (except "-") and skills with candidate counts, most common first. */
export async function getFilterOptions(): Promise<FilterOptions> {
  const c = candidateTable;
  const cs = candidateSkillTable;
  const countries = await db
    .select({ name: c.country, count: count() })
    .from(c)
    .where(ne(c.country, '-'))
    .groupBy(c.country)
    .orderBy(desc(count()), asc(c.country));
  const skills = await db
    .select({ name: cs.skill, count: count() })
    .from(cs)
    .groupBy(cs.skill)
    .orderBy(desc(count()), asc(cs.skill));
  return { countries, skills };
}

function toSummary(candidate: Candidate, skills: CandidateSkill[]): CandidateSummary {
  const topSkills = [...skills]
    .sort(
      (a, b) => strength(b) - strength(a) || (a.skill < b.skill ? -1 : a.skill > b.skill ? 1 : 0)
    )
    .slice(0, TOP_SKILLS)
    .map((row) => row.skill);
  return {
    id: candidate.id,
    name: `${candidate.firstName} ${candidate.lastName}`,
    country: candidate.country,
    yearsExperience: candidate.yearsExperience,
    monthlyRate: candidate.fullTimeRateNormalized,
    rateUnverified: candidate.rateUnverified,
    availability: {
      fullTime: candidate.fullTime,
      partTime: candidate.partTime,
      contractor: candidate.contractor,
      employee: candidate.employee,
    },
    biography: candidate.biography ?? '',
    topSkills,
  };
}

function skillLabel(row: CandidateSkill | undefined): string {
  if (!row) return '';
  const roles = `${row.roleCount} ${row.roleCount === 1 ? 'role' : 'roles'}`;
  if (row.roleCount > 0) return `${row.skill} in ${roles}${row.inBio ? ' and bio' : ''}`;
  return `${row.skill} in bio`;
}

function experienceLabel(candidate: Candidate, { minYears, maxYears }: SearchFilters): string {
  const label = `${candidate.yearsExperience} yrs experience`;
  if (minYears !== null && maxYears !== null) return `${label} (${minYears}–${maxYears})`;
  if (minYears !== null) return `${label} (min ${minYears})`;
  if (maxYears !== null) return `${label} (max ${maxYears})`;
  return label;
}

function salaryLabel(candidate: Candidate, { minSalary, maxSalary }: SearchFilters): string {
  const label = `${usd.format((candidate.fullTimeRateNormalized ?? 0) * 12)}/yr`;
