import { sql } from 'drizzle-orm';
import { db } from '@/db';
import { getCandidateProfile } from '@/lib/profile';
import { GET } from '@/app/api/candidates/[id]/route';

const ok = (label: string, cond: boolean, extra = '') =>
  console.log(`${cond ? 'PASS' : 'FAIL'} ${label} ${extra}`);

async function main() {
  // 1
  const [top] = (await db.all(
    sql`select candidate_id as id, count(*) as n from experiences group by candidate_id order by n desc, candidate_id limit 1`
  )) as { id: number; n: number }[];
  const [yrs] = (await db.all(
    sql`select years_experience as y from candidates where id = ${top.id}`
  )) as { y: number }[];
  const p = (await getCandidateProfile(top.id))!;
  ok('1 count', p.experiences.length === top.n, `id=${top.id} sql=${top.n} got=${p.experiences.length}`);
  ok('1 years', p.candidate.yearsExperience === yrs.y, `sql=${yrs.y} got=${p.candidate.yearsExperience}`);

  // 2,3,5,6 over many candidates
  const ids = ((await db.all(sql`select id from candidates`)) as { id: number }[]).map((r) => r.id);
  let bad2 = 0, bad3 = 0, bad5 = 0, bad6 = 0, badEdu = 0;
  const re = /^\d{4}-\d{2}-\d{2}$/;
  const skillRows = (await db.all(
    sql`select candidate_id as c, skill, in_bio as b, role_count as r from candidate_skills`
  )) as { c: number; skill: string; b: number; r: number }[];
  for (const id of ids) {
    const pr = (await getCandidateProfile(id))!;
    const starts = pr.experiences.map((e) => e.startDate);
    for (let i = 1; i < starts.length; i++) {
      const a = starts[i - 1], b = starts[i];
      if (a === null && b !== null) bad2++;
      if (a !== null && b !== null && a < b) bad2++;
    }
    const es = pr.education.map((e) => e.startDate);
    for (let i = 1; i < es.length; i++) {
      const a = es[i - 1], b = es[i];
      if ((a === null && b !== null) || (a !== null && b !== null && a < b)) badEdu++;
    }
    for (const e of pr.experiences) {
      if (e.counted && e.effectiveEndDate === null) bad3++;
      if (!e.counted && (e.effectiveEndDate !== null || e.excludedReason === null)) bad3++;
      for (const d of [e.startDate, e.endDate, e.effectiveEndDate]) if (d !== null && !re.test(d)) bad5++;
    }
    for (const e of pr.education)
      for (const d of [e.startDate, e.endDate]) if (d !== null && !re.test(d)) bad5++;
    const mine = skillRows
      .filter((r) => r.c === id)
      .map((r) => ({ name: r.skill, inBio: !!r.b, roleCount: r.r }))
      .sort((x, y) => y.roleCount + +y.inBio - (x.roleCount + +x.inBio) || (x.name < y.name ? -1 : x.name > y.name ? 1 : 0));
    if (JSON.stringify(mine) !== JSON.stringify(pr.skills)) bad6++;
    if (JSON.stringify(pr.candidate.topSkills) !== JSON.stringify(mine.slice(0, 8).map((s) => s.name))) bad6++;
  }
  ok('2 order', bad2 === 0, `candidates=${ids.length} violations=${bad2} (edu violations=${badEdu})`);
  ok('3 counted/effectiveEnd', bad3 === 0, `violations=${bad3}`);
  ok('5 dates', bad5 === 0, `violations=${bad5}`);
  ok('6 skills + topSkills', bad6 === 0, `violations=${bad6}`);

  // 4
  const [intern] = (await db.all(
    sql`select candidate_id as c, id, position from experiences where position like '%Intern%' order by id limit 1`
  )) as { c: number; id: number; position: string }[];
  const pi = (await getCandidateProfile(intern.c))!;
  const job = pi.experiences.find((e) => e.position === intern.position)!;
  ok('4 intern', !job.counted && job.excludedReason === 'intern', `cand=${intern.c} "${intern.position}" → counted=${job.counted} reason=${job.excludedReason}`);

  // 7
  const none = await getCandidateProfile(99999999);
  ok('7 unknown', none === null, `got=${JSON.stringify(none)}`);

  // 8
  const call = async (id: string) => {
    const res = await GET(new Request(`http://x/api/candidates/${id}`), { params: Promise.resolve({ id }) });
    return { status: res.status, body: await res.json() };
  };
  for (const id of ['abc', '0', '99999999', String(top.id), '01', '-1', '1.5']) {
    const r = await call(id);
    console.log(`8 id=${JSON.stringify(id)} → ${r.status} ${r.status === 200 ? `candidate.id=${r.body.candidate.id}` : JSON.stringify(r.body)}`);
  }

  const sample = (await getCandidateProfile(intern.c))!;
  console.log(JSON.stringify({ ...sample, candidate: { ...sample.candidate, biography: sample.candidate.biography.slice(0, 60) + '…' }, experiences: sample.experiences.map((e) => ({ ...e, description: e.description.slice(0, 40) + '…' })) }, null, 2));
}
main();

