/** Newest start first, null starts last; stable, so ties keep input order. Drops `start`. */
function byStartDesc<T extends { start: Date | null }>(items: T[]): Omit<T, 'start'>[] {
  const time = (item: T) => (item.start ? item.start.getTime() : -Infinity);
  return [...items]
    .sort((a, b) => (time(a) === time(b) ? 0 : time(b) > time(a) ? 1 : -1))
    .map(({ start: _start, ...rest }) => rest);
}

